import * as THREE from 'three';
import {texture} from './materials.js';
const vertex=`varying vec3 vP;varying vec2 vUV;void main(){vUV=uv;vP=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`;
const noise=`float hash(vec3 p){p=fract(p*.3183099+vec3(.1,.2,.3));p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}float noise(vec3 x){vec3 i=floor(x),f=fract(x);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}float fbm(vec3 p){return .5*noise(p)+.25*noise(p*2.1)+.125*noise(p*4.3)+.0625*noise(p*8.1);}`;
export function createSun(scene){
 const group=new THREE.Group();scene.add(group);
 const mat=new THREE.ShaderMaterial({uniforms:{time:{value:0},map:{value:texture('2k_sun.jpg')}},vertexShader:vertex,fragmentShader:`uniform float time;uniform sampler2D map;varying vec3 vP;varying vec2 vUV;${noise}void main(){vec3 p=normalize(vP);float n=fbm(p*13.+vec3(time*.06,0.,time*.025));float fine=noise(p*125.+time*.03);vec3 image=texture2D(map,vUV+vec2(time*.001,0.)).rgb;float energy=clamp(n*.65+image.r*.35+fine*.08,0.,1.);vec3 color=mix(vec3(.12,.002,.0001),vec3(1.8,.24,.004),smoothstep(.24,.78,energy));color=mix(color,vec3(2.4,.8,.035),smoothstep(.80,.94,energy));gl_FragColor=vec4(color,1.);}`,toneMapped:false});
 const surface=new THREE.Mesh(new THREE.SphereGeometry(3,96,64),mat);group.add(surface);
 const coronaMat=new THREE.ShaderMaterial({uniforms:{time:{value:0}},vertexShader:`uniform float time;varying vec3 n;varying vec3 vp;varying vec3 p;void main(){p=position;float wave=sin(position.x*7.+time*.9)*sin(position.y*5.-time*.7)+sin(position.z*9.+time*.6)*.4;vec3 flowing=position*(1.+wave*.035);n=normalize(normalMatrix*normal);vp=(modelViewMatrix*vec4(flowing,1.)).xyz;gl_Position=projectionMatrix*vec4(vp,1.);}`,fragmentShader:`uniform float time;varying vec3 n;varying vec3 vp;varying vec3 p;${noise}void main(){float rim=pow(1.-abs(dot(normalize(n),normalize(-vp))),3.5);float stream=fbm(normalize(p)*17.+vec3(time*.32,-time*.18,time*.24));float pulse=.75+.25*sin(time*.8+p.y*5.);vec3 fire=mix(vec3(1.4,.07,.002),vec3(2.2,.42,.015),stream);gl_FragColor=vec4(fire,rim*stream*pulse*.6);}`,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,side:THREE.BackSide,toneMapped:false});
 const corona=new THREE.Mesh(new THREE.SphereGeometry(3.32,96,64),coronaMat);group.add(corona);
 const loops=[];
 for(let k=0;k<20;k++){
  const angle=k*2.399,axis=new THREE.Vector3(Math.sin(angle),Math.cos(angle),Math.sin(angle*1.7)).normalize(),side=new THREE.Vector3().crossVectors(axis,new THREE.Vector3(0,1,0)).normalize(),points=[];
  for(let j=0;j<=40;j++){const t=j/40,a=(t-.5)*.32;points.push(axis.clone().multiplyScalar((3+.5*Math.sin(t*Math.PI)) *Math.cos(a)).addScaledVector(side,3*Math.sin(a)))}
  const curve=new THREE.CatmullRomCurve3(points);const loop=new THREE.Mesh(new THREE.TubeGeometry(curve,40,.015+(k%3)*.006,5,false),new THREE.ShaderMaterial({uniforms:{time:{value:0},seed:{value:k*1.37},axis:{value:axis},side:{value:side}},vertexShader:`uniform float time;uniform float seed;uniform vec3 axis;uniform vec3 side;varying float life;varying float along;void main(){float phase=fract(time/(7.+mod(seed,5.))+seed);life=sin(phase*3.14159265);vec3 p=position;float height=max(length(p)-3.,0.);float anchor=smoothstep(0.,.22,height);vec3 radial=normalize(p);p-=radial*height*(1.-life);p+=axis*anchor*life*(.18+.35*sin(phase*3.14159265));p+=side*anchor*sin(time*.8+seed+height*5.)*.16*life;along=height;gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.);}`,fragmentShader:`uniform float time;uniform float seed;varying float life;varying float along;void main(){float flow=.6+.4*sin(along*25.-time*3.+seed);gl_FragColor=vec4(mix(vec3(2.,.08,.002),vec3(3.4,.65,.025),flow),pow(max(life,0.),.7)*.85);}`,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false}));group.add(loop);loops.push(loop)
 }
 return {group,surface,update(t){const seconds=t/.35;mat.uniforms.time.value=seconds*.75;coronaMat.uniforms.time.value=seconds;group.rotation.y=t*.007;loops.forEach(l=>{l.material.uniforms.time.value=seconds})}};
}
export function createStars(scene){
 let seed=93;const rnd=()=>{seed=seed*16807%2147483647;return(seed-1)/2147483646};const positions=[],colors=[],sizes=[];
 for(let i=0;i<3500;i++){const z=rnd()*2-1,a=rnd()*Math.PI*2,r=400+rnd()*300,s=Math.sqrt(1-z*z);positions.push(r*s*Math.cos(a),r*z,r*s*Math.sin(a));const tint=rnd();colors.push(tint<.18?.66:1,tint>.85?.8:.9,tint>.85?.6:1);sizes.push(rnd()<.025?5+rnd()*3:1+rnd()*2)}
 const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geometry.setAttribute('size',new THREE.Float32BufferAttribute(sizes,1));
 const material=new THREE.ShaderMaterial({uniforms:{pixelRatio:{value:Math.min(devicePixelRatio,2)}},vertexShader:`attribute vec3 color;attribute float size;uniform float pixelRatio;varying vec3 c;varying float s;void main(){c=color;s=size;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);gl_PointSize=size*pixelRatio*3.;}`,fragmentShader:`varying vec3 c;varying float s;void main(){vec2 p=gl_PointCoord-.5;float r=length(p);if(r>.5)discard;float core=exp(-r*r*150.);float halo=exp(-r*r*24.)*.18;float rays=s>4.?pow(max(0.,1.-abs(p.x)*45.),3.)*exp(-abs(p.y)*10.)*.12+pow(max(0.,1.-abs(p.y)*45.),3.)*exp(-abs(p.x)*10.)*.12:0.;gl_FragColor=vec4(c*(core*2.+halo+rays),1.);}`,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false});
 const stars=new THREE.Points(geometry,material);stars.frustumCulled=false;scene.add(stars);return stars;
}
